using CustomCodeFramework.Postgres.EntityFramework.Configurations;using Dhole.Content.Domain.Settings.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Dhole.Content.Persistence.Configurations.Settings;internal sealed class SiteSettingConfiguration:EntityTypeConfigurationBase<SiteSetting,Guid>{public override void Configure(EntityTypeBuilder<SiteSetting>b){base.Configure(b);b.ToTable("site_settings");b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.SiteKey).HasMaxLength(80).IsRequired();b.Property(x=>x.Key).HasMaxLength(200).IsRequired();b.Property(x=>x.ValueJson).HasColumnType("jsonb").IsRequired();b.HasIndex(x=>new{x.SiteKey,x.Key}).IsUnique().HasFilter("is_deleted = false");}}
